MIRRORS = ("desktop/src-tauri",)       # build copies (gitignored); refreshed if present
SUITES = ["app/backtest/tsg/test_tsg_runner.py",       # + 9 intrabar FIX1
          "app/engine/tsg/test_tsg_live_core.py",      # 16 (hard stop, live side)
          "app/engine/tsg/test_tsg_sl_per_lot.py",     # 53 (incl. end-to-end intrabar on a synthetic corpus)
          "app/parity/test_parity.py"]


def die(msg, wrote=False):
    print(f"\n✗ {msg}" + ("" if wrote else "\nNothing was written."))
    sys.exit(1)


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    flags = {a for a in sys.argv[1:] if a.startswith("--")}
    root = os.path.abspath(args[0] if args else os.getcwd())
    if not (os.path.isdir(os.path.join(root, "backend", "app")) and os.path.isdir(os.path.join(root, "frontend", "src"))):
        die(f"{root} is not the scalp-app repo root (expected backend/app and frontend/src)")
    print(f"── {FENCE} → {root}")

    for rel in EDITS:
        p = os.path.join(root, rel)
        if not os.path.isfile(p):
            die(f"missing {rel}")
        txt = open(p, encoding="utf-8").read()
        if FENCE in txt:
            die(f"{rel} already carries {FENCE} — already applied")
        for parent in PARENTS.get(rel, []):
            if parent not in txt:
                die(f"{rel} lacks parent fence {parent} — apply apply_tsg_intrabar_skip_partial.py first")
    if "--allow-dirty" not in flags and os.path.isdir(os.path.join(root, ".git")):
        try:
            st = subprocess.run(["git", "status", "--porcelain", "--"] + list(EDITS), cwd=root,
                                capture_output=True, text=True, timeout=30).stdout
        except Exception as e:
            st = ""
            print(f"  (git status unavailable: {e!r} — continuing)")
        dirty = [ln for ln in st.splitlines() if ln[:2].strip()]
        if dirty:
            die("uncommitted changes in target files (commit/stash, or pass --allow-dirty):\n  " + "\n  ".join(dirty))

    staged = {}
    for rel, edits in EDITS.items():
        txt = open(os.path.join(root, rel), encoding="utf-8").read()
        for i, (old, new) in enumerate(edits, 1):
            n = txt.count(old)
            if n != 1:
                die(f"{rel}: anchor {i}/{len(edits)} found {n}× (expected 1):\n{old[:300]}")
            txt = txt.replace(old, new)
        staged[rel] = txt
    for rel, txt in staged.items():
        if rel.endswith(".py"):
            try:
                compile(txt, rel, "exec")
            except SyntaxError as e:
                die(f"{rel} does not compile after staging: {e}")
    print(f"  preflight ok — {sum(len(e) for e in EDITS.values())} anchored edits in {len(EDITS)} files")

    touched = []

    def write(path, txt):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        bak = None
        if os.path.exists(path):
            bak = f"{path}.bak-{FENCE}"
            shutil.copy2(path, bak)
        touched.append((path, bak))
        with open(path, "w", encoding="utf-8") as f:
            f.write(txt)

    def rollback(why):
        for path, bak in reversed(touched):
            try:
                if bak:
                    shutil.copy2(bak, path)
                    os.remove(bak)
                elif os.path.exists(path):
                    os.remove(path)
            except Exception as e:
                print(f"  !! could not restore {path}: {e!r}")
        die(f"{why}\nEvery file it touched was restored.", wrote=True)

    for rel, txt in staged.items():
        write(os.path.join(root, rel), txt)
        print(f"  wrote {rel}")
        for m in MIRRORS:
            if os.path.isdir(os.path.join(root, m, rel.split("/")[0])):
                write(os.path.join(root, m, rel), txt)
                print(f"    mirrored → {m}/{rel}")

    if "--skip-tests" in flags:
        print("\n  --skip-tests: suites not run")
    else:
        be = os.path.join(root, "backend")
        env = dict(os.environ, PYTHONPATH=be)
        for suite in SUITES:
            print(f"\n── running {suite} (a few minutes)")
            r = subprocess.run([sys.executable, suite], cwd=be, env=env, capture_output=True, text=True)
            tail = "\n".join((r.stdout or "").strip().splitlines()[-2:])
            print("  " + tail.replace("\n", "\n  "))
            if r.returncode != 0:
                print("\n".join(l for l in (r.stdout + r.stderr).splitlines()
                                if "FAIL" in l or "Error" in l or "assert" in l.lower())[-3000:])
                rollback(f"{suite} failed")
        esb = os.path.join(root, "frontend", "node_modules", ".bin", "esbuild")
        if os.path.exists(esb):
            r = subprocess.run([esb, os.path.join(root, "frontend/src/pages/Backtest.jsx"), "--loader:.jsx=jsx",
                                "--log-level=error"], capture_output=True, text=True)
            if r.returncode != 0:
                print(r.stderr[-2000:])
                rollback("esbuild could not parse Backtest.jsx")
            print("  esbuild parsed Backtest.jsx")
        else:
            print("  (frontend/node_modules/.bin/esbuild missing — JSX parse skipped; build-scalp.sh will compile)")

    print(f"\n✓ {FENCE} applied. Backups: *.bak-{FENCE}")
    print("  Next: ./desktop/build-scalp.sh both   — outside market hours")
    print("  Then: Backtest → TSG_V1, exit 15:26, MTM check INTRABAR, Hard stop × SL 1.05, 2020-01-01 → 2026-08-07")
    print("        (compare with 93f2a3cc close ₹53.85L and 2ee25cfb old-intrabar ₹39.51L).")


if __name__ == "__main__":
    main()
